insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Cardiovascular$q$,$q$mcq$q$,$q$A nurse reviews data for a client admitted with heart failure. Weight: 70.2 kg on day 1, 71.4 kg on day 2, and 72.9 kg on day 3. The client has new bibasilar crackles, 2+ pitting ankle edema, urine output of 600 mL over 24 hours, BP 148/92 mmHg, and SpO2 93% on room air. Which analysis of these cues is most accurate?$q$,$q$[{"id":"a","text":"The weight gain reflects expected improvement in nutrition."},{"id":"b","text":"The client has developed a bacterial pneumonia."},{"id":"c","text":"The client is dehydrated from excessive diuretic therapy."},{"id":"d","text":"The client is developing fluid volume overload from worsening heart failure."}]$q$::jsonb,$q${"ids":["d"]}$q$::jsonb,$q$Weight rose about 2.7 kg in 48 hours (1 kg is roughly 1 L of retained fluid) along with new crackles, edema, hypertension and low urine output. Together these cues show fluid retention from worsening heart failure. Dehydration would cause weight loss, and nothing in the data points to infection.$q$,'draft',$q$Physiological Adaptation$q$,$q$Analyze Cues$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic B01 (Part B); intended difficulty medium; subtopic: Heart failure.$q$,$q$Weight rose about 2.7 kg in 48 hours (1 kg is roughly 1 L of retained fluid) along with new crackles, edema, hypertension and low urine output. Together these cues show fluid retention from worsening heart failure. Dehydration would cause weight loss, and nothing in the data points to infection.$q$,$q${"a":{"is_correct":false,"explanation":"A gain of 2.7 kg in 48 hours with new crackles and edema is retained fluid, not improved nutrition."},"b":{"is_correct":false,"explanation":"Pneumonia usually causes fever, a productive cough and focal findings, and would not explain the edema and weight gain."},"c":{"is_correct":false,"explanation":"Dehydration causes weight loss, dry mucous membranes and concentrated urine, not weight gain with crackles and edema."},"d":{"is_correct":true,"explanation":"Rapid weight gain with new crackles, edema and low urine output shows retained fluid from worsening heart failure."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$A nurse reviews data for a client admitted with heart failure. Weight: 70.2 kg on day 1, 71.4 kg on day 2, and 72.9 kg on day 3. The client has new bibasilar crackles, 2+ pitting ankle edema, urine output of 600 mL over 24 hours, BP 148/92 mmHg, and SpO2 93% on room air. Which analysis of these cues is most accurate?$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Medical-Surgical$q$,$q$mcq$q$,$q$A client with type 1 diabetes is admitted with a glucose of 486 mg/dL, deep rapid respirations, and a fruity breath odor. Arterial blood gases show pH 7.21, PaCO2 26 mmHg, and HCO3 12 mEq/L. Which interpretation is correct?$q$,$q$[{"id":"a","text":"Metabolic acidosis with respiratory compensation"},{"id":"b","text":"Metabolic alkalosis with respiratory compensation"},{"id":"c","text":"Respiratory alkalosis without compensation"},{"id":"d","text":"Respiratory acidosis with renal compensation"}]$q$::jsonb,$q${"ids":["a"]}$q$::jsonb,$q$A low pH with a low bicarbonate shows metabolic acidosis caused by ketone accumulation. The low PaCO2 and the deep, rapid (Kussmaul) respirations show the lungs are blowing off carbon dioxide to compensate.$q$,'draft',$q$Physiological Adaptation$q$,$q$Analyze Cues$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic B02 (Part B); intended difficulty medium; subtopic: Diabetic ketoacidosis.$q$,$q$A low pH with a low bicarbonate shows metabolic acidosis caused by ketone accumulation. The low PaCO2 and the deep, rapid (Kussmaul) respirations show the lungs are blowing off carbon dioxide to compensate.$q$,$q${"a":{"is_correct":true,"explanation":"A low pH with a low HCO3 shows metabolic acidosis, and the low PaCO2 shows respiratory compensation."},"b":{"is_correct":false,"explanation":"Metabolic alkalosis would show a high pH and a high bicarbonate."},"c":{"is_correct":false,"explanation":"Respiratory alkalosis would have a high pH; here the pH is low and the low PaCO2 is compensation."},"d":{"is_correct":false,"explanation":"Respiratory acidosis would show a high PaCO2, not a low one."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$A client with type 1 diabetes is admitted with a glucose of 486 mg/dL, deep rapid respirations, and a fruity breath odor. Arterial blood gases show pH 7.21, PaCO2 26 mmHg, and HCO3 12 mEq/L. Which interpretation is correct?$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Emergency and Critical Care$q$,$q$mcq$q$,$q$A client on postoperative day 2 after bowel resection has a temperature of 38.9°C, HR 118/min, RR 26/min, BP 92/54 mmHg, WBC 18,000/mm3, lactate 3.8 mmol/L, and new confusion. Which analysis best fits these cues?$q$,$q$[{"id":"a","text":"Uncontrolled incisional pain"},{"id":"b","text":"An expected postoperative inflammatory response"},{"id":"c","text":"Anxiety related to hospitalization"},{"id":"d","text":"Sepsis with early signs of poor tissue perfusion"}]$q$::jsonb,$q${"ids":["d"]}$q$::jsonb,$q$Fever, tachycardia, tachypnea and leukocytosis suggest infection. Hypotension, a raised lactate and new confusion show that organs are not being perfused well. This pattern is sepsis and is not a normal postoperative response.$q$,'draft',$q$Physiological Adaptation$q$,$q$Analyze Cues$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic B03 (Part B); intended difficulty medium; subtopic: Sepsis.$q$,$q$Fever, tachycardia, tachypnea and leukocytosis suggest infection. Hypotension, a raised lactate and new confusion show that organs are not being perfused well. This pattern is sepsis and is not a normal postoperative response.$q$,$q${"a":{"is_correct":false,"explanation":"Pain can raise the heart rate but does not explain fever, leukocytosis or a high lactate."},"b":{"is_correct":false,"explanation":"A normal postoperative response does not cause hypotension, a high lactate or new confusion."},"c":{"is_correct":false,"explanation":"Anxiety does not cause hypotension, fever or an elevated lactate."},"d":{"is_correct":true,"explanation":"Fever, tachycardia, tachypnea, a high WBC and lactate, hypotension and confusion show infection with poor perfusion."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$A client on postoperative day 2 after bowel resection has a temperature of 38.9°C, HR 118/min, RR 26/min, BP 92/54 mmHg, WBC 18,000/mm3, lactate 3.8 mmol/L, and new confusion. Which analysis best fits these cues?$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Laboratory and Diagnostics$q$,$q$mcq$q$,$q$A client taking warfarin reports bleeding gums. The INR is 5.8 (therapeutic range 2 to 3). Which analysis is most accurate?$q$,$q$[{"id":"a","text":"The INR shows excessive anticoagulation and a high risk of serious bleeding."},{"id":"b","text":"The bleeding gums show that the warfarin dose is too low."},{"id":"c","text":"The INR shows the client has developed a clotting disorder."},{"id":"d","text":"The INR is expected for a client taking warfarin and needs no action."}]$q$::jsonb,$q${"ids":["a"]}$q$::jsonb,$q$An INR of 5.8 is well above the therapeutic range of 2 to 3 and means the blood is clotting too slowly. Bleeding gums are an early bleeding sign, so the client is at high risk of serious hemorrhage and the provider must be notified.$q$,'draft',$q$Reduction of Risk Potential$q$,$q$Analyze Cues$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic B04 (Part B); intended difficulty easy; subtopic: Anticoagulant therapy.$q$,$q$An INR of 5.8 is well above the therapeutic range of 2 to 3 and means the blood is clotting too slowly. Bleeding gums are an early bleeding sign, so the client is at high risk of serious hemorrhage and the provider must be notified.$q$,$q${"a":{"is_correct":true,"explanation":"An INR far above the 2 to 3 range with bleeding shows over-anticoagulation and a high risk of hemorrhage."},"b":{"is_correct":false,"explanation":"Bleeding shows too much anticoagulation, not too little."},"c":{"is_correct":false,"explanation":"A high INR from warfarin is a drug effect and does not mean a clotting disorder."},"d":{"is_correct":false,"explanation":"An INR of 5.8 is not expected on warfarin and needs action."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$A client taking warfarin reports bleeding gums. The INR is 5.8 (therapeutic range 2 to 3). Which analysis is most accurate?$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Laboratory and Diagnostics$q$,$q$mcq$q$,$q$A client with end-stage kidney disease missed dialysis for one week and reports muscle weakness. Serum potassium is 6.8 mEq/L and the ECG shows tall, peaked T waves. Which conclusion is most accurate?$q$,$q$[{"id":"a","text":"The muscle weakness is caused by low calcium and not by potassium."},{"id":"b","text":"Peaked T waves are a normal variant for clients with kidney disease."},{"id":"c","text":"The findings show hypokalemia related to fluid overload."},{"id":"d","text":"Hyperkalemia from missed dialysis is putting the client at risk for a life-threatening dysrhythmia."}]$q$::jsonb,$q${"ids":["d"]}$q$::jsonb,$q$The kidneys excrete potassium, so it accumulates when dialysis is missed. Peaked T waves are an early ECG sign of hyperkalemia and can progress to ventricular dysrhythmias and cardiac arrest, so this is an emergency.$q$,'draft',$q$Reduction of Risk Potential$q$,$q$Analyze Cues$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic B05 (Part B); intended difficulty medium; subtopic: Hyperkalemia.$q$,$q$The kidneys excrete potassium, so it accumulates when dialysis is missed. Peaked T waves are an early ECG sign of hyperkalemia and can progress to ventricular dysrhythmias and cardiac arrest, so this is an emergency.$q$,$q${"a":{"is_correct":false,"explanation":"Low calcium can cause weakness but does not explain a potassium of 6.8 or peaked T waves."},"b":{"is_correct":false,"explanation":"Peaked T waves are an abnormal sign of hyperkalemia, not a normal variant."},"c":{"is_correct":false,"explanation":"A potassium of 6.8 mEq/L is high (hyperkalemia), not low."},"d":{"is_correct":true,"explanation":"Missed dialysis lets potassium accumulate, and peaked T waves signal a risk of fatal dysrhythmias."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$A client with end-stage kidney disease missed dialysis for one week and reports muscle weakness. Serum potassium is 6.8 mEq/L and the ECG shows tall, peaked T waves. Which conclusion is most accurate?$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Mental Health$q$,$q$sata$q$,$q$A nurse assesses a 68-year-old client who recently lost a spouse. Which findings indicate a high risk for suicide? Select all that apply.$q$,$q$[{"id":"a","text":"Reports occasional mild headaches."},{"id":"b","text":"States, \"Everyone would be better off without me.\""},{"id":"c","text":"Has been giving away treasured belongings to family members."},{"id":"d","text":"Attends a weekly grief-support group."},{"id":"e","text":"Has a written plan and access to a firearm at home."}]$q$::jsonb,$q${"ids":["b","c","e"]}$q$::jsonb,$q$Statements of being a burden, giving away possessions, and a specific plan with access to lethal means are strong warning signs of high risk. Mild headaches are unrelated, and attending a support group is a protective factor.$q$,'draft',$q$Psychosocial Integrity$q$,$q$Analyze Cues$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic B06 (Part B); intended difficulty medium; subtopic: Suicide risk.$q$,$q$Statements of being a burden, giving away possessions, and a specific plan with access to lethal means are strong warning signs of high risk. Mild headaches are unrelated, and attending a support group is a protective factor.$q$,$q${"a":{"is_correct":false,"explanation":"Mild headaches are not related to suicide risk."},"b":{"is_correct":true,"explanation":"Statements of being a burden show hopelessness and are a strong warning sign."},"c":{"is_correct":true,"explanation":"Giving away treasured belongings often shows the client has decided to die."},"d":{"is_correct":false,"explanation":"Support-group attendance is a protective factor, not a risk indicator."},"e":{"is_correct":true,"explanation":"A specific plan with access to lethal means is one of the highest-risk indicators."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$A nurse assesses a 68-year-old client who recently lost a spouse. Which findings indicate a high risk for suicide? Select all that apply.$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Safety and Infection Control$q$,$q$sata$q$,$q$An 82-year-old client on postoperative day 2 after hip surgery is receiving oxycodone and furosemide, uses a walker, and has nocturia. The client is confused at night. Which factors increase this client's risk for falls? Select all that apply.$q$,$q$[{"id":"a","text":"Uses the call light appropriately"},{"id":"b","text":"Nighttime confusion"},{"id":"c","text":"Opioid analgesic therapy"},{"id":"d","text":"Diuretic-related nocturia"},{"id":"e","text":"Alert and oriented during the day"}]$q$::jsonb,$q${"ids":["b","c","d"]}$q$::jsonb,$q$Opioids cause sedation and dizziness, diuretics cause urgent trips to the toilet at night, and nighttime confusion impairs judgment. Being oriented in the day and using the call light are protective, not risk factors.$q$,'draft',$q$Safety and Infection Prevention and Control$q$,$q$Analyze Cues$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic B07 (Part B); intended difficulty medium; subtopic: Fall risk.$q$,$q$Opioids cause sedation and dizziness, diuretics cause urgent trips to the toilet at night, and nighttime confusion impairs judgment. Being oriented in the day and using the call light are protective, not risk factors.$q$,$q${"a":{"is_correct":false,"explanation":"Using the call light appropriately lowers the risk."},"b":{"is_correct":true,"explanation":"Nighttime confusion impairs judgment and safe mobility."},"c":{"is_correct":true,"explanation":"Opioids cause sedation, dizziness and slowed reactions that increase falls."},"d":{"is_correct":true,"explanation":"Diuretics create urgency and nocturia, leading to unassisted trips to the toilet at night."},"e":{"is_correct":false,"explanation":"Being oriented during the day does not raise the fall risk."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$An 82-year-old client on postoperative day 2 after hip surgery is receiving oxycodone and furosemide, uses a walker, and has nocturia. The client is confused at night. Which factors increase this client's risk for falls? Select all that apply.$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Fundamentals$q$,$q$sata$q$,$q$A bedbound client has a stage 2 sacral pressure injury, a Braden score of 11, urinary incontinence, and a serum albumin of 2.6 g/dL. Which factors are contributing to the risk for skin breakdown? Select all that apply.$q$,$q$[{"id":"a","text":"Prolonged immobility"},{"id":"b","text":"Moisture from incontinence"},{"id":"c","text":"Well-fitting footwear"},{"id":"d","text":"Poor nutritional status"},{"id":"e","text":"Age-related vision changes"}]$q$::jsonb,$q${"ids":["a","b","d"]}$q$::jsonb,$q$Pressure, moisture and poor nutrition (shown by the low albumin) all reduce the skin's tolerance for pressure injury. A low Braden score confirms high risk. Vision changes and well-fitting footwear do not contribute to sacral skin breakdown.$q$,'draft',$q$Basic Care and Comfort$q$,$q$Analyze Cues$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic B08 (Part B); intended difficulty medium; subtopic: Pressure injury.$q$,$q$Pressure, moisture and poor nutrition (shown by the low albumin) all reduce the skin's tolerance for pressure injury. A low Braden score confirms high risk. Vision changes and well-fitting footwear do not contribute to sacral skin breakdown.$q$,$q${"a":{"is_correct":true,"explanation":"Immobility prolongs pressure over bony areas such as the sacrum."},"b":{"is_correct":true,"explanation":"Moisture softens skin and makes it more vulnerable to breakdown."},"c":{"is_correct":false,"explanation":"Footwear fit is unrelated to sacral skin breakdown."},"d":{"is_correct":true,"explanation":"A low albumin shows poor nutrition, which weakens tissue and delays healing."},"e":{"is_correct":false,"explanation":"Age-related vision changes do not affect pressure over the sacrum."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$A bedbound client has a stage 2 sacral pressure injury, a Braden score of 11, urinary incontinence, and a serum albumin of 2.6 g/dL. Which factors are contributing to the risk for skin breakdown? Select all that apply.$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Pharmacology$q$,$q$mcq$q$,$q$A client taking digoxin and furosemide reports nausea and blurred yellow-green vision. The HR is 52/min, serum potassium is 3.1 mEq/L, and the digoxin level is 2.4 ng/mL (therapeutic 0.5 to 2.0). Which analysis is most accurate?$q$,$q$[{"id":"a","text":"A therapeutic digoxin effect that needs no action"},{"id":"b","text":"An allergic reaction to furosemide"},{"id":"c","text":"Digoxin toxicity that is worsened by hypokalemia"},{"id":"d","text":"Underdosing of digoxin with rebound tachycardia"}]$q$::jsonb,$q${"ids":["c"]}$q$::jsonb,$q$The level is above the therapeutic range and the client has classic toxicity signs (nausea, visual changes, bradycardia). Furosemide lowers potassium, and hypokalemia increases digoxin toxicity, so both problems must be addressed.$q$,'draft',$q$Pharmacological and Parenteral Therapies$q$,$q$Analyze Cues$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic B09 (Part B); intended difficulty hard; subtopic: Digoxin toxicity.$q$,$q$The level is above the therapeutic range and the client has classic toxicity signs (nausea, visual changes, bradycardia). Furosemide lowers potassium, and hypokalemia increases digoxin toxicity, so both problems must be addressed.$q$,$q${"a":{"is_correct":false,"explanation":"A level of 2.4 ng/mL with these symptoms is toxic, not therapeutic."},"b":{"is_correct":false,"explanation":"An allergy to furosemide would cause hives or wheezing, not yellow-green vision with bradycardia."},"c":{"is_correct":true,"explanation":"A level above 2.0 with nausea, visual changes and bradycardia is toxicity, and hypokalemia makes digoxin more toxic."},"d":{"is_correct":false,"explanation":"Underdosing would lower the level and would not cause bradycardia and visual changes."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$A client taking digoxin and furosemide reports nausea and blurred yellow-green vision. The HR is 52/min, serum potassium is 3.1 mEq/L, and the digoxin level is 2.4 ng/mL (therapeutic 0.5 to 2.0). Which analysis is most accurate?$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Maternal and Newborn$q$,$q$mcq$q$,$q$A client at 34 weeks of gestation has BP 152/98 mmHg, 3+ proteinuria, a severe headache, and blurred vision. Which analysis is most accurate?$q$,$q$[{"id":"a","text":"Preeclampsia with severe features"},{"id":"b","text":"A urinary tract infection"},{"id":"c","text":"Normal physiological changes of pregnancy"},{"id":"d","text":"Gestational diabetes mellitus"}]$q$::jsonb,$q${"ids":["a"]}$q$::jsonb,$q$New hypertension with proteinuria after 20 weeks indicates preeclampsia, and the severe headache and visual disturbance are severe features that show central nervous system involvement and risk of seizure.$q$,'draft',$q$Health Promotion and Maintenance$q$,$q$Analyze Cues$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic B10 (Part B); intended difficulty medium; subtopic: Preeclampsia.$q$,$q$New hypertension with proteinuria after 20 weeks indicates preeclampsia, and the severe headache and visual disturbance are severe features that show central nervous system involvement and risk of seizure.$q$,$q${"a":{"is_correct":true,"explanation":"Hypertension, proteinuria, headache and visual disturbance after 20 weeks indicate severe preeclampsia."},"b":{"is_correct":false,"explanation":"A urinary tract infection would not cause hypertension with visual changes."},"c":{"is_correct":false,"explanation":"Severe hypertension with headache and visual changes is not a normal pregnancy change."},"d":{"is_correct":false,"explanation":"Gestational diabetes involves glucose and does not explain the blood pressure and neurologic symptoms."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$A client at 34 weeks of gestation has BP 152/98 mmHg, 3+ proteinuria, a severe headache, and blurred vision. Which analysis is most accurate?$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Cardiovascular$q$,$q$mcq$q$,$q$A client reports substernal chest pressure that radiates to the left arm, with diaphoresis and nausea. The ECG shows ST-segment elevation in leads V2 to V4. Which hypothesis should the nurse prioritize?$q$,$q$[{"id":"a","text":"Anxiety-related chest tightness"},{"id":"b","text":"Musculoskeletal chest wall pain"},{"id":"c","text":"Gastroesophageal reflux"},{"id":"d","text":"Acute myocardial infarction"}]$q$::jsonb,$q${"ids":["d"]}$q$::jsonb,$q$Pressure radiating to the arm with diaphoresis and ST elevation is an acute ST-elevation myocardial infarction until proven otherwise. It is the most life-threatening explanation and needs immediate treatment.$q$,'draft',$q$Physiological Adaptation$q$,$q$Prioritize Hypotheses$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic B11 (Part B); intended difficulty medium; subtopic: Acute coronary syndrome.$q$,$q$Pressure radiating to the arm with diaphoresis and ST elevation is an acute ST-elevation myocardial infarction until proven otherwise. It is the most life-threatening explanation and needs immediate treatment.$q$,$q${"a":{"is_correct":false,"explanation":"Anxiety does not cause ST-segment elevation."},"b":{"is_correct":false,"explanation":"Chest wall pain does not cause ST elevation or diaphoresis with radiating pressure."},"c":{"is_correct":false,"explanation":"Reflux can mimic chest pain but does not cause ST elevation."},"d":{"is_correct":true,"explanation":"Pressure radiating to the arm, diaphoresis and ST elevation show an acute myocardial infarction, which is life-threatening."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$A client reports substernal chest pressure that radiates to the left arm, with diaphoresis and nausea. The ECG shows ST-segment elevation in leads V2 to V4. Which hypothesis should the nurse prioritize?$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Medical-Surgical$q$,$q$mcq$q$,$q$One day after abdominal surgery, a client has BP 86/50 mmHg, HR 124/min, cool and clammy skin, an increasingly distended abdomen, and rapidly increasing bloody drain output. Which hypothesis should the nurse prioritize?$q$,$q$[{"id":"a","text":"Hemorrhage with hypovolemic shock"},{"id":"b","text":"Surgical site pain"},{"id":"c","text":"Postoperative ileus"},{"id":"d","text":"Opioid-related sedation"}]$q$::jsonb,$q${"ids":["a"]}$q$::jsonb,$q$Hypotension, tachycardia, cool clammy skin, abdominal distention and bloody drainage indicate internal bleeding causing hypovolemic shock. This is the most urgent life-threatening cause and takes priority over ileus or pain.$q$,'draft',$q$Physiological Adaptation$q$,$q$Prioritize Hypotheses$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic B12 (Part B); intended difficulty medium; subtopic: Postoperative hemorrhage.$q$,$q$Hypotension, tachycardia, cool clammy skin, abdominal distention and bloody drainage indicate internal bleeding causing hypovolemic shock. This is the most urgent life-threatening cause and takes priority over ileus or pain.$q$,$q${"a":{"is_correct":true,"explanation":"Hypotension, tachycardia, cool clammy skin, distention and bloody drainage show hemorrhage with shock."},"b":{"is_correct":false,"explanation":"Pain raises heart rate and blood pressure and does not explain hypotension with bloody drainage."},"c":{"is_correct":false,"explanation":"Ileus causes distention but not shock or rapidly increasing bloody drainage."},"d":{"is_correct":false,"explanation":"Sedation would slow the heart and breathing, not cause tachycardia."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$One day after abdominal surgery, a client has BP 86/50 mmHg, HR 124/min, cool and clammy skin, an increasingly distended abdomen, and rapidly increasing bloody drain output. Which hypothesis should the nurse prioritize?$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Medical-Surgical$q$,$q$mcq$q$,$q$A client with a fractured femur 24 hours ago suddenly develops dyspnea and confusion. The SpO2 is 86%, and petechiae appear over the chest. Which hypothesis should the nurse prioritize?$q$,$q$[{"id":"a","text":"Fluid volume overload"},{"id":"b","text":"Anxiety related to pain"},{"id":"c","text":"Fat embolism syndrome"},{"id":"d","text":"Community-acquired pneumonia"}]$q$::jsonb,$q${"ids":["c"]}$q$::jsonb,$q$Long-bone fractures release fat globules that lodge in the lungs and brain. The classic triad is respiratory distress, neurologic change and petechiae, usually within 24 to 72 hours of injury.$q$,'draft',$q$Reduction of Risk Potential$q$,$q$Prioritize Hypotheses$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic B13 (Part B); intended difficulty hard; subtopic: Fat embolism.$q$,$q$Long-bone fractures release fat globules that lodge in the lungs and brain. The classic triad is respiratory distress, neurologic change and petechiae, usually within 24 to 72 hours of injury.$q$,$q${"a":{"is_correct":false,"explanation":"Fluid overload causes crackles and edema, not petechiae."},"b":{"is_correct":false,"explanation":"Anxiety does not cause an SpO2 of 86% or petechiae."},"c":{"is_correct":true,"explanation":"Respiratory distress, confusion and petechiae after a long-bone fracture are the classic signs of fat embolism."},"d":{"is_correct":false,"explanation":"Pneumonia would not typically appear within 24 hours of a fracture with petechiae."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$A client with a fractured femur 24 hours ago suddenly develops dyspnea and confusion. The SpO2 is 86%, and petechiae appear over the chest. Which hypothesis should the nurse prioritize?$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Respiratory$q$,$q$mcq$q$,$q$A client with COPD receiving oxygen at 10 L/min by mask is drowsy and has a respiratory rate of 8/min. The SpO2 is 99%. Which hypothesis should the nurse prioritize?$q$,$q$[{"id":"a","text":"Acute hypercapnic respiratory failure from hypoventilation"},{"id":"b","text":"Hypoglycemia"},{"id":"c","text":"Successful treatment with normal sleepiness"},{"id":"d","text":"Pulmonary embolism"}]$q$::jsonb,$q${"ids":["a"]}$q$::jsonb,$q$Drowsiness with a slow respiratory rate in a client with COPD who is receiving high-flow oxygen suggests carbon dioxide retention. A normal SpO2 does not exclude hypercapnia, and the client is at risk of respiratory arrest.$q$,'draft',$q$Physiological Adaptation$q$,$q$Prioritize Hypotheses$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic B14 (Part B); intended difficulty hard; subtopic: Hypercapnic respiratory failure.$q$,$q$Drowsiness with a slow respiratory rate in a client with COPD who is receiving high-flow oxygen suggests carbon dioxide retention. A normal SpO2 does not exclude hypercapnia, and the client is at risk of respiratory arrest.$q$,$q${"a":{"is_correct":true,"explanation":"Drowsiness and a slow respiratory rate after high-flow oxygen in COPD suggest carbon dioxide retention, and a normal SpO2 does not exclude it."},"b":{"is_correct":false,"explanation":"Hypoglycemia can cause drowsiness, but the slow respirations after high-flow oxygen point to carbon dioxide retention."},"c":{"is_correct":false,"explanation":"A respiratory rate of 8 with drowsiness is dangerous, not normal sleepiness."},"d":{"is_correct":false,"explanation":"Pulmonary embolism typically causes fast breathing, not a rate of 8."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$A client with COPD receiving oxygen at 10 L/min by mask is drowsy and has a respiratory rate of 8/min. The SpO2 is 99%. Which hypothesis should the nurse prioritize?$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Mental Health$q$,$q$mcq$q$,$q$On day 2 of admission, a client with alcohol use disorder has tremors, diaphoresis, HR 118/min, BP 168/98 mmHg, and agitation, and reports seeing insects on the walls. Which hypothesis should the nurse prioritize?$q$,$q$[{"id":"a","text":"Generalized anxiety disorder"},{"id":"b","text":"Seasonal affective disorder"},{"id":"c","text":"Alcohol withdrawal delirium (delirium tremens)"},{"id":"d","text":"Relapse of schizophrenia"}]$q$::jsonb,$q${"ids":["c"]}$q$::jsonb,$q$Autonomic hyperactivity with visual hallucinations 48 to 72 hours after the last drink is characteristic of delirium tremens. It has a significant mortality risk and needs urgent treatment and seizure precautions.$q$,'draft',$q$Psychosocial Integrity$q$,$q$Prioritize Hypotheses$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic B15 (Part B); intended difficulty medium; subtopic: Alcohol withdrawal.$q$,$q$Autonomic hyperactivity with visual hallucinations 48 to 72 hours after the last drink is characteristic of delirium tremens. It has a significant mortality risk and needs urgent treatment and seizure precautions.$q$,$q${"a":{"is_correct":false,"explanation":"Generalized anxiety does not cause hallucinations with severe autonomic hyperactivity."},"b":{"is_correct":false,"explanation":"Seasonal affective disorder is a mood disorder and does not fit these findings."},"c":{"is_correct":true,"explanation":"Autonomic hyperactivity with visual hallucinations 2 to 3 days after alcohol cessation is delirium tremens."},"d":{"is_correct":false,"explanation":"A schizophrenia relapse does not explain the timing and autonomic signs of withdrawal."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$On day 2 of admission, a client with alcohol use disorder has tremors, diaphoresis, HR 118/min, BP 168/98 mmHg, and agitation, and reports seeing insects on the walls. Which hypothesis should the nurse prioritize?$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Safety and Infection Control$q$,$q$mcq$q$,$q$A client receiving chemotherapy has an absolute neutrophil count of 300/mm3 and a temperature of 38.6°C. The client reports feeling tired. Which hypothesis should the nurse prioritize?$q$,$q$[{"id":"a","text":"An allergic reaction"},{"id":"b","text":"A serious infection in a neutropenic client"},{"id":"c","text":"Expected fatigue from chemotherapy"},{"id":"d","text":"Mild dehydration"}]$q$::jsonb,$q${"ids":["b"]}$q$::jsonb,$q$Neutropenic clients cannot mount a normal inflammatory response, so fever may be the only sign of overwhelming infection. Fever with a low neutrophil count is a medical emergency needing cultures and immediate antibiotics.$q$,'draft',$q$Safety and Infection Prevention and Control$q$,$q$Prioritize Hypotheses$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic B16 (Part B); intended difficulty medium; subtopic: Neutropenic fever.$q$,$q$Neutropenic clients cannot mount a normal inflammatory response, so fever may be the only sign of overwhelming infection. Fever with a low neutrophil count is a medical emergency needing cultures and immediate antibiotics.$q$,$q${"a":{"is_correct":false,"explanation":"An allergic reaction does not typically cause fever with neutropenia."},"b":{"is_correct":true,"explanation":"Fever with a very low neutrophil count is a medical emergency because infection can progress rapidly to sepsis."},"c":{"is_correct":false,"explanation":"Fatigue is expected, but fever with neutropenia must not be attributed to chemotherapy effects."},"d":{"is_correct":false,"explanation":"Dehydration does not explain a fever with an absolute neutrophil count of 300."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$A client receiving chemotherapy has an absolute neutrophil count of 300/mm3 and a temperature of 38.6°C. The client reports feeling tired. Which hypothesis should the nurse prioritize?$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Pharmacology$q$,$q$mcq$q$,$q$Ten minutes into a rapid vancomycin infusion, a client develops flushing of the face, neck and upper torso with itching. BP is 104/62 mmHg, the lungs are clear, and there is no wheezing or lip swelling. Which hypothesis is best supported by these cues?$q$,$q$[{"id":"a","text":"Contact dermatitis from the tape"},{"id":"b","text":"Sepsis"},{"id":"c","text":"Anaphylaxis with airway compromise"},{"id":"d","text":"An infusion-rate related reaction to vancomycin"}]$q$::jsonb,$q${"ids":["d"]}$q$::jsonb,$q$Flushing and itching of the face, neck and upper trunk during a rapid vancomycin infusion is a rate-related histamine reaction (vancomycin flushing syndrome). Clear lungs and no wheezing or swelling make anaphylaxis less likely, though the nurse must keep monitoring.$q$,'draft',$q$Pharmacological and Parenteral Therapies$q$,$q$Prioritize Hypotheses$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic B17 (Part B); intended difficulty medium; subtopic: Vancomycin infusion reaction.$q$,$q$Flushing and itching of the face, neck and upper trunk during a rapid vancomycin infusion is a rate-related histamine reaction (vancomycin flushing syndrome). Clear lungs and no wheezing or swelling make anaphylaxis less likely, though the nurse must keep monitoring.$q$,$q${"a":{"is_correct":false,"explanation":"Tape dermatitis would be localized to the skin under the tape."},"b":{"is_correct":false,"explanation":"Sepsis would not develop within 10 minutes of starting an infusion with this flushing pattern."},"c":{"is_correct":false,"explanation":"Anaphylaxis would include wheezing, swelling or marked hypotension, which are absent."},"d":{"is_correct":true,"explanation":"Flushing and itching of the face, neck and upper trunk during a rapid infusion is a rate-related vancomycin reaction."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$Ten minutes into a rapid vancomycin infusion, a client develops flushing of the face, neck and upper torso with itching. BP is 104/62 mmHg, the lungs are clear, and there is no wheezing or lip swelling. Which hypothesis is best supported by these cues?$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Neurologic and Sensory$q$,$q$mcq$q$,$q$A client 2 days after a stroke coughs and has a wet, gurgling voice after sips of water. The SpO2 is 94%. Which hypothesis should the nurse prioritize?$q$,$q$[{"id":"a","text":"Aspiration related to impaired swallowing"},{"id":"b","text":"Anxiety about eating"},{"id":"c","text":"Dry mouth from oxygen therapy"},{"id":"d","text":"Seasonal allergies"}]$q$::jsonb,$q${"ids":["a"]}$q$::jsonb,$q$Coughing and a wet voice after swallowing show that fluid is entering the airway. Aspiration can cause pneumonia and airway obstruction, so oral intake should be stopped until a swallow evaluation is done.$q$,'draft',$q$Basic Care and Comfort$q$,$q$Prioritize Hypotheses$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic B18 (Part B); intended difficulty medium; subtopic: Dysphagia after stroke.$q$,$q$Coughing and a wet voice after swallowing show that fluid is entering the airway. Aspiration can cause pneumonia and airway obstruction, so oral intake should be stopped until a swallow evaluation is done.$q$,$q${"a":{"is_correct":true,"explanation":"Coughing and a wet voice after swallowing show liquid is entering the airway."},"b":{"is_correct":false,"explanation":"Anxiety does not produce coughing and a wet voice with swallowing."},"c":{"is_correct":false,"explanation":"Oxygen-related dry mouth does not cause a gurgling voice and coughing."},"d":{"is_correct":false,"explanation":"Allergies do not cause a wet voice and coughing after sips."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$A client 2 days after a stroke coughs and has a wet, gurgling voice after sips of water. The SpO2 is 94%. Which hypothesis should the nurse prioritize?$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Medical-Surgical$q$,$q$mcq$q$,$q$Six hours after a total thyroidectomy, a client reports tingling around the mouth. Carpopedal spasm occurs when the blood pressure cuff is inflated, and Chvostek's sign is positive. Which hypothesis should the nurse prioritize?$q$,$q$[{"id":"a","text":"Thyroid storm"},{"id":"b","text":"Hypocalcemia from parathyroid gland injury"},{"id":"c","text":"Postoperative anxiety"},{"id":"d","text":"Hypercalcemia"}]$q$::jsonb,$q${"ids":["b"]}$q$::jsonb,$q$Perioral tingling, carpopedal spasm (Trousseau's sign) and Chvostek's sign are classic signs of low calcium, a complication when the parathyroid glands are damaged or removed. Laryngospasm and seizures can follow.$q$,'draft',$q$Reduction of Risk Potential$q$,$q$Prioritize Hypotheses$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic B19 (Part B); intended difficulty medium; subtopic: Hypocalcemia after thyroidectomy.$q$,$q$Perioral tingling, carpopedal spasm (Trousseau's sign) and Chvostek's sign are classic signs of low calcium, a complication when the parathyroid glands are damaged or removed. Laryngospasm and seizures can follow.$q$,$q${"a":{"is_correct":false,"explanation":"Thyroid storm causes fever, tachycardia and agitation, which are not described."},"b":{"is_correct":true,"explanation":"Perioral tingling, carpopedal spasm and Chvostek's sign are signs of low calcium from parathyroid injury."},"c":{"is_correct":false,"explanation":"Anxiety does not produce positive Chvostek's and Trousseau's signs."},"d":{"is_correct":false,"explanation":"Hypercalcemia causes weakness and lethargy, not tingling and muscle spasm."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$Six hours after a total thyroidectomy, a client reports tingling around the mouth. Carpopedal spasm occurs when the blood pressure cuff is inflated, and Chvostek's sign is positive. Which hypothesis should the nurse prioritize?$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Neurologic and Sensory$q$,$q$mcq$q$,$q$A client suddenly has slurred speech and right-sided arm weakness. The spouse reports the client was last seen normal 40 minutes ago. Which hypothesis should the nurse prioritize?$q$,$q$[{"id":"a","text":"An anxiety attack"},{"id":"b","text":"Migraine with aura"},{"id":"c","text":"Vitamin B12 deficiency"},{"id":"d","text":"Acute ischemic stroke with a time-sensitive treatment window"}]$q$::jsonb,$q${"ids":["d"]}$q$::jsonb,$q$Sudden speech and motor deficits with a known time last seen normal indicate a stroke. Treatment such as thrombolysis is time-dependent, so the nurse activates the stroke response and checks the glucose to rule out a mimic.$q$,'draft',$q$Physiological Adaptation$q$,$q$Prioritize Hypotheses$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic B20 (Part B); intended difficulty medium; subtopic: Acute ischemic stroke.$q$,$q$Sudden speech and motor deficits with a known time last seen normal indicate a stroke. Treatment such as thrombolysis is time-dependent, so the nurse activates the stroke response and checks the glucose to rule out a mimic.$q$,$q${"a":{"is_correct":false,"explanation":"Anxiety does not cause focal weakness and slurred speech."},"b":{"is_correct":false,"explanation":"A migraine aura develops gradually and does not usually cause sudden weakness."},"c":{"is_correct":false,"explanation":"Vitamin B12 deficiency develops over months, not suddenly."},"d":{"is_correct":true,"explanation":"Sudden focal speech and motor deficits with a known last-seen-normal time indicate a stroke in the treatment window."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$A client suddenly has slurred speech and right-sided arm weakness. The spouse reports the client was last seen normal 40 minutes ago. Which hypothesis should the nurse prioritize?$q$);

