insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Maternal and Newborn$q$,$q$sata$q$,$q$A breastfeeding client on postpartum day 4 has firm, tender, engorged breasts. Which interventions should the nurse include in the plan of care? Select all that apply.$q$,$q$[{"id":"a","text":"Apply warm compresses or take a warm shower just before feeding"},{"id":"b","text":"Breastfeed frequently, at least every 2 to 3 hours"},{"id":"c","text":"Limit feedings to every 6 hours to rest the breasts"},{"id":"d","text":"Apply cold packs between feedings for comfort"},{"id":"e","text":"Restrict fluid intake to reduce milk production"}]$q$::jsonb,$q${"ids":["a","b","d"]}$q$::jsonb,$q$Frequent milk removal relieves engorgement, warmth before feeding helps milk flow and cold packs afterward reduce swelling and pain. Spacing feedings out or restricting fluids worsens engorgement and risks mastitis.$q$,'draft',$q$Health Promotion and Maintenance$q$,$q$Generate Solutions$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic B24 (Part B); intended difficulty easy; subtopic: Breast engorgement.$q$,$q$Frequent milk removal relieves engorgement, warmth before feeding helps milk flow and cold packs afterward reduce swelling and pain. Spacing feedings out or restricting fluids worsens engorgement and risks mastitis.$q$,$q${"a":{"is_correct":true,"explanation":"Warmth before feeding helps let-down and milk flow."},"b":{"is_correct":true,"explanation":"Frequent milk removal relieves engorgement."},"c":{"is_correct":false,"explanation":"Long gaps between feedings worsen engorgement and raise the risk of mastitis."},"d":{"is_correct":true,"explanation":"Cold packs between feedings reduce swelling and discomfort."},"e":{"is_correct":false,"explanation":"Restricting fluids does not relieve engorgement and can lead to dehydration."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$A breastfeeding client on postpartum day 4 has firm, tender, engorged breasts. Which interventions should the nurse include in the plan of care? Select all that apply.$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Mental Health$q$,$q$mcq$q$,$q$A client who is hyperventilating states, "I can't breathe and I think I'm dying." The client is diagnosed with a panic attack. Which action should the nurse plan first?$q$,$q$[{"id":"a","text":"Leave the client alone to reduce stimulation"},{"id":"b","text":"Explain the physiology of anxiety in detail"},{"id":"c","text":"Stay with the client in a calm, quiet area and coach slow breathing"},{"id":"d","text":"Ask the client to describe what triggered the attack"}]$q$::jsonb,$q${"ids":["c"]}$q$::jsonb,$q$During a panic attack the client cannot process complex information. Staying present, keeping the environment calm and using brief, simple instructions to slow breathing is the safest first step.$q$,'draft',$q$Psychosocial Integrity$q$,$q$Generate Solutions$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic B25 (Part B); intended difficulty easy; subtopic: Panic attack.$q$,$q$During a panic attack the client cannot process complex information. Staying present, keeping the environment calm and using brief, simple instructions to slow breathing is the safest first step.$q$,$q${"a":{"is_correct":false,"explanation":"Leaving the client alone increases fear and the sense of danger."},"b":{"is_correct":false,"explanation":"A client in panic cannot process a long explanation."},"c":{"is_correct":true,"explanation":"Staying with the client, keeping the setting calm and coaching slow breathing reduces panic safely."},"d":{"is_correct":false,"explanation":"Discussing triggers should wait until the panic has passed."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$A client who is hyperventilating states, "I can't breathe and I think I'm dying." The client is diagnosed with a panic attack. Which action should the nurse plan first?$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Safety and Infection Control$q$,$q$mcq$q$,$q$A client has a productive cough, night sweats, and weight loss and is suspected of having pulmonary tuberculosis. Which action should the nurse take?$q$,$q$[{"id":"a","text":"Place the client in a room with another client who has a cough"},{"id":"b","text":"Use contact precautions with a gown and gloves"},{"id":"c","text":"Place the client in a private room and wear a surgical mask"},{"id":"d","text":"Place the client in a negative-pressure room and wear a fit-tested N95 respirator"}]$q$::jsonb,$q${"ids":["d"]}$q$::jsonb,$q$Tuberculosis spreads by airborne droplet nuclei, so airborne precautions are needed: a negative-pressure room and a fit-tested N95 or higher respirator for staff. A surgical mask does not protect the nurse.$q$,'draft',$q$Safety and Infection Prevention and Control$q$,$q$Take Action$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic B26 (Part B); intended difficulty easy; subtopic: Airborne precautions.$q$,$q$Tuberculosis spreads by airborne droplet nuclei, so airborne precautions are needed: a negative-pressure room and a fit-tested N95 or higher respirator for staff. A surgical mask does not protect the nurse.$q$,$q${"a":{"is_correct":false,"explanation":"Placing the client with another client risks spreading infection."},"b":{"is_correct":false,"explanation":"Tuberculosis is not spread by contact, so a gown and gloves alone do not protect."},"c":{"is_correct":false,"explanation":"A surgical mask does not protect the nurse from airborne particles."},"d":{"is_correct":true,"explanation":"Tuberculosis spreads through the air, so it requires a negative-pressure room and a fit-tested N95 respirator."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$A client has a productive cough, night sweats, and weight loss and is suspected of having pulmonary tuberculosis. Which action should the nurse take?$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Leadership and Delegation$q$,$q$mcq$q$,$q$A nurse realizes that a client received a double dose of a prescribed antihypertensive medication. Which action should the nurse take first?$q$,$q$[{"id":"a","text":"Assess the client's blood pressure and clinical status, then notify the provider"},{"id":"b","text":"Wait to see whether symptoms develop before reporting"},{"id":"c","text":"Say nothing to the client to avoid causing worry"},{"id":"d","text":"Complete an incident report before contacting the provider"}]$q$::jsonb,$q${"ids":["a"]}$q$::jsonb,$q$Client safety comes first: assess for harm such as hypotension, then notify the provider so treatment can be ordered. The event is disclosed and documented in an incident report afterward, not instead of care.$q$,'draft',$q$Management of Care$q$,$q$Take Action$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic B29 (Part B); intended difficulty medium; subtopic: Medication error.$q$,$q$Client safety comes first: assess for harm such as hypotension, then notify the provider so treatment can be ordered. The event is disclosed and documented in an incident report afterward, not instead of care.$q$,$q${"a":{"is_correct":true,"explanation":"The nurse first assesses the client for harm and notifies the provider so treatment can be ordered."},"b":{"is_correct":false,"explanation":"Waiting for symptoms delays treatment and risks serious harm."},"c":{"is_correct":false,"explanation":"Clients have a right to be told about an error that affects their care."},"d":{"is_correct":false,"explanation":"Documentation should follow care and must not delay notifying the provider."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$A nurse realizes that a client received a double dose of a prescribed antihypertensive medication. Which action should the nurse take first?$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Safety and Infection Control$q$,$q$mcq$q$,$q$A nurse implemented a fall-prevention plan for a client at high risk for falls. Which finding best shows that the plan is effective?$q$,$q$[{"id":"a","text":"A visitor turned off the bed alarm"},{"id":"b","text":"The client asks for help before getting up and has had no falls in 72 hours"},{"id":"c","text":"The client walks alone to the bathroom at night"},{"id":"d","text":"The client refuses to use the call light"}]$q$::jsonb,$q${"ids":["b"]}$q$::jsonb,$q$An effective plan changes behavior and outcomes: the client asks for assistance and no falls occur. The other findings show that the safeguards are not being used.$q$,'draft',$q$Safety and Infection Prevention and Control$q$,$q$Evaluate Outcomes$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic B27 (Part B); intended difficulty easy; subtopic: Fall prevention evaluation.$q$,$q$An effective plan changes behavior and outcomes: the client asks for assistance and no falls occur. The other findings show that the safeguards are not being used.$q$,$q${"a":{"is_correct":false,"explanation":"A disabled bed alarm removes a safeguard."},"b":{"is_correct":true,"explanation":"Asking for help and having no falls shows the client is using the plan and the plan works."},"c":{"is_correct":false,"explanation":"Walking alone at night is the risky behavior the plan is meant to prevent."},"d":{"is_correct":false,"explanation":"Refusing the call light shows the plan is not being followed."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$A nurse implemented a fall-prevention plan for a client at high risk for falls. Which finding best shows that the plan is effective?$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Leadership and Delegation$q$,$q$mcq$q$,$q$A nurse teaches a client about an advance directive. Which client statement shows that the teaching was effective?$q$,$q$[{"id":"a","text":"\"My family will not be able to see it once it is signed.\""},{"id":"b","text":"\"I can change or cancel my directive at any time.\""},{"id":"c","text":"\"I must have a lawyer complete it for it to be valid.\""},{"id":"d","text":"\"It only takes effect if I am hospitalized for surgery.\""}]$q$::jsonb,$q${"ids":["b"]}$q$::jsonb,$q$A competent client may revise or revoke an advance directive at any time. A lawyer is not required, the directive applies whenever the client cannot decide, and family and providers should have copies.$q$,'draft',$q$Management of Care$q$,$q$Evaluate Outcomes$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic B30 (Part B); intended difficulty medium; subtopic: Advance directive teaching.$q$,$q$A competent client may revise or revoke an advance directive at any time. A lawyer is not required, the directive applies whenever the client cannot decide, and family and providers should have copies.$q$,$q${"a":{"is_correct":false,"explanation":"Copies should be shared with family and the health care team."},"b":{"is_correct":true,"explanation":"A competent client may revise or cancel an advance directive at any time."},"c":{"is_correct":false,"explanation":"A lawyer is not required for a valid advance directive."},"d":{"is_correct":false,"explanation":"A directive applies whenever the client cannot make decisions, not only for surgery."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$A nurse teaches a client about an advance directive. Which client statement shows that the teaching was effective?$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Pharmacology$q$,$q$mcq$q$,$q$A prescriber orders 1,000 mL of 0.9% sodium chloride to infuse over 8 hours by infusion pump. At what rate in mL/hr should the nurse set the pump?$q$,$q$[{"id":"a","text":"100 mL/hr"},{"id":"b","text":"125 mL/hr"},{"id":"c","text":"150 mL/hr"},{"id":"d","text":"175 mL/hr"}]$q$::jsonb,$q${"ids":["b"]}$q$::jsonb,$q$Pumps are set in mL/hr, and the rate equals the total volume divided by the time in hours: 1,000 mL ÷ 8 hours = 125 mL/hr.$q$,'draft',$q$Pharmacological and Parenteral Therapies$q$,$q$Take Action$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic C01 (Part C); intended difficulty easy; subtopic: IV infusion rate (mL/hr).$q$,$q$Pumps are set in mL/hr, and the rate equals the total volume divided by the time in hours: 1,000 mL ÷ 8 hours = 125 mL/hr.$q$,$q${"a":{"is_correct":false,"explanation":"This rate would take 10 hours to infuse the 1,000 mL."},"b":{"is_correct":true,"explanation":"This is correct: 1,000 mL divided by 8 hours is 125 mL/hr."},"c":{"is_correct":false,"explanation":"This rate would infuse 1,000 mL in about 6.7 hours."},"d":{"is_correct":false,"explanation":"This rate would infuse 1,000 mL in about 5.7 hours."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$A prescriber orders 1,000 mL of 0.9% sodium chloride to infuse over 8 hours by infusion pump. At what rate in mL/hr should the nurse set the pump?$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Pharmacology$q$,$q$mcq$q$,$q$The nurse will infuse 500 mL of lactated Ringer's solution over 4 hours by gravity. The tubing drop factor is 15 gtt/mL. How many drops per minute should the nurse set? (Round to the nearest whole number.)$q$,$q$[{"id":"a","text":"21 gtt/min"},{"id":"b","text":"31 gtt/min"},{"id":"c","text":"42 gtt/min"},{"id":"d","text":"125 gtt/min"}]$q$::jsonb,$q${"ids":["b"]}$q$::jsonb,$q$Drops per minute = (volume × drop factor) ÷ minutes = (500 × 15) ÷ 240 = 31.25, which rounds to 31 gtt/min.$q$,'draft',$q$Pharmacological and Parenteral Therapies$q$,$q$Take Action$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic C02 (Part C); intended difficulty medium; subtopic: Gravity drip rate (gtt/min).$q$,$q$Drops per minute = (volume × drop factor) ÷ minutes = (500 × 15) ÷ 240 = 31.25, which rounds to 31 gtt/min.$q$,$q${"a":{"is_correct":false,"explanation":"This rate would take about 6 hours to infuse 500 mL."},"b":{"is_correct":true,"explanation":"This is correct: (500 × 15) ÷ 240 minutes is about 31 gtt/min."},"c":{"is_correct":false,"explanation":"This rate would infuse 500 mL in about 3 hours."},"d":{"is_correct":false,"explanation":"This is the mL/hr rate (500 ÷ 4), not the drops per minute."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$The nurse will infuse 500 mL of lactated Ringer's solution over 4 hours by gravity. The tubing drop factor is 15 gtt/mL. How many drops per minute should the nurse set? (Round to the nearest whole number.)$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Pharmacology$q$,$q$mcq$q$,$q$A prescriber orders acetaminophen 15 mg/kg by mouth for a child who weighs 18 kg. The oral suspension is 160 mg per 5 mL. How many mL should the nurse give? (Round to the nearest tenth.)$q$,$q$[{"id":"a","text":"4.2 mL"},{"id":"b","text":"8.4 mL"},{"id":"c","text":"9.6 mL"},{"id":"d","text":"16.9 mL"}]$q$::jsonb,$q${"ids":["b"]}$q$::jsonb,$q$The dose is 15 mg/kg × 18 kg = 270 mg. At 160 mg per 5 mL (32 mg/mL) the volume is 270 ÷ 32 = 8.4 mL.$q$,'draft',$q$Pharmacological and Parenteral Therapies$q$,$q$Take Action$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic C03 (Part C); intended difficulty medium; subtopic: Weight-based pediatric dose.$q$,$q$The dose is 15 mg/kg × 18 kg = 270 mg. At 160 mg per 5 mL (32 mg/mL) the volume is 270 ÷ 32 = 8.4 mL.$q$,$q${"a":{"is_correct":false,"explanation":"This volume delivers about 134 mg, only half the ordered dose."},"b":{"is_correct":true,"explanation":"This is correct: 15 mg/kg × 18 kg is 270 mg, and 270 ÷ 32 mg/mL is 8.4 mL."},"c":{"is_correct":false,"explanation":"This volume delivers about 307 mg, more than the ordered dose."},"d":{"is_correct":false,"explanation":"This volume delivers about 541 mg, about double the ordered dose."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$A prescriber orders acetaminophen 15 mg/kg by mouth for a child who weighs 18 kg. The oral suspension is 160 mg per 5 mL. How many mL should the nurse give? (Round to the nearest tenth.)$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Pharmacology$q$,$q$mcq$q$,$q$A prescriber orders levothyroxine 0.1 mg by mouth daily. The tablets available contain 50 mcg each. How many tablets should the nurse administer?$q$,$q$[{"id":"a","text":"0.5 tablet"},{"id":"b","text":"1 tablet"},{"id":"c","text":"2 tablets"},{"id":"d","text":"4 tablets"}]$q$::jsonb,$q${"ids":["c"]}$q$::jsonb,$q$Convert first: 0.1 mg × 1,000 = 100 mcg. Then 100 mcg ÷ 50 mcg per tablet = 2 tablets.$q$,'draft',$q$Pharmacological and Parenteral Therapies$q$,$q$Take Action$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic C04 (Part C); intended difficulty easy; subtopic: Unit conversion (mg to mcg).$q$,$q$Convert first: 0.1 mg × 1,000 = 100 mcg. Then 100 mcg ÷ 50 mcg per tablet = 2 tablets.$q$,$q${"a":{"is_correct":false,"explanation":"This would deliver only 25 mcg, a quarter of the ordered 100 mcg."},"b":{"is_correct":false,"explanation":"This would deliver only 50 mcg, half of the ordered 100 mcg."},"c":{"is_correct":true,"explanation":"This is correct: 0.1 mg is 100 mcg, which is 2 tablets of 50 mcg."},"d":{"is_correct":false,"explanation":"This would deliver 200 mcg, double the dose, from a conversion error."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$A prescriber orders levothyroxine 0.1 mg by mouth daily. The tablets available contain 50 mcg each. How many tablets should the nurse administer?$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Pharmacology$q$,$q$mcq$q$,$q$A prescriber orders gentamicin 5 mg/kg IV once daily. The client weighs 154 lb, and the vial contains 40 mg/mL. How many mL should the nurse prepare? (Round to the nearest tenth.)$q$,$q$[{"id":"a","text":"7.0 mL"},{"id":"b","text":"8.8 mL"},{"id":"c","text":"9.6 mL"},{"id":"d","text":"19.3 mL"}]$q$::jsonb,$q${"ids":["b"]}$q$::jsonb,$q$Convert the weight: 154 lb ÷ 2.2 = 70 kg. The dose is 5 mg/kg × 70 kg = 350 mg. Volume = 350 mg ÷ 40 mg/mL = 8.75, which rounds to 8.8 mL.$q$,'draft',$q$Pharmacological and Parenteral Therapies$q$,$q$Take Action$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic C05 (Part C); intended difficulty hard; subtopic: Weight-based dose with lb to kg conversion.$q$,$q$Convert the weight: 154 lb ÷ 2.2 = 70 kg. The dose is 5 mg/kg × 70 kg = 350 mg. Volume = 350 mg ÷ 40 mg/mL = 8.75, which rounds to 8.8 mL.$q$,$q${"a":{"is_correct":false,"explanation":"This volume delivers 280 mg, less than the ordered 350 mg."},"b":{"is_correct":true,"explanation":"This is correct: 154 lb is 70 kg, 5 mg/kg is 350 mg, and 350 ÷ 40 is 8.75 mL, rounded to 8.8 mL."},"c":{"is_correct":false,"explanation":"This volume delivers about 384 mg, more than the ordered dose."},"d":{"is_correct":false,"explanation":"Using 154 without converting to kilograms gives 770 mg, more than double the dose."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$A prescriber orders gentamicin 5 mg/kg IV once daily. The client weighs 154 lb, and the vial contains 40 mg/mL. How many mL should the nurse prepare? (Round to the nearest tenth.)$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Pharmacology$q$,$q$mcq$q$,$q$A heparin infusion contains 25,000 units in 250 mL of 5% dextrose in water. The prescriber orders 1,200 units/hr. At what rate in mL/hr should the nurse set the pump?$q$,$q$[{"id":"a","text":"8 mL/hr"},{"id":"b","text":"10 mL/hr"},{"id":"c","text":"12 mL/hr"},{"id":"d","text":"24 mL/hr"}]$q$::jsonb,$q${"ids":["c"]}$q$::jsonb,$q$The concentration is 25,000 units ÷ 250 mL = 100 units/mL. The rate is 1,200 units/hr ÷ 100 units/mL = 12 mL/hr.$q$,'draft',$q$Pharmacological and Parenteral Therapies$q$,$q$Take Action$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic C06 (Part C); intended difficulty medium; subtopic: Heparin infusion rate.$q$,$q$The concentration is 25,000 units ÷ 250 mL = 100 units/mL. The rate is 1,200 units/hr ÷ 100 units/mL = 12 mL/hr.$q$,$q${"a":{"is_correct":false,"explanation":"This rate delivers 800 units/hr, less than the ordered 1,200 units/hr."},"b":{"is_correct":false,"explanation":"This rate delivers 1,000 units/hr, less than the ordered dose."},"c":{"is_correct":true,"explanation":"This is correct: the concentration is 100 units/mL, so 1,200 units/hr is 12 mL/hr."},"d":{"is_correct":false,"explanation":"This rate delivers 2,400 units/hr, double the ordered dose."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$A heparin infusion contains 25,000 units in 250 mL of 5% dextrose in water. The prescriber orders 1,200 units/hr. At what rate in mL/hr should the nurse set the pump?$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Pharmacology$q$,$q$mcq$q$,$q$A child who weighs 20 kg is prescribed amoxicillin 500 mg by mouth every 12 hours. The drug guide lists a safe range of 25 to 45 mg/kg/day in divided doses. What should the nurse do?$q$,$q$[{"id":"a","text":"Hold the dose and clarify with the prescriber because the daily dose exceeds the safe range"},{"id":"b","text":"Give the dose because it is within the safe range"},{"id":"c","text":"Give half of the dose and document it"},{"id":"d","text":"Give the dose and monitor for a rash"}]$q$::jsonb,$q${"ids":["a"]}$q$::jsonb,$q$The daily dose is 500 mg × 2 = 1,000 mg, which is 1,000 ÷ 20 = 50 mg/kg/day. This is above the listed maximum of 45 mg/kg/day, so the nurse holds the dose and clarifies the order before giving it.$q$,'draft',$q$Pharmacological and Parenteral Therapies$q$,$q$Take Action$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic C07 (Part C); intended difficulty hard; subtopic: Safe dose range check.$q$,$q$The daily dose is 500 mg × 2 = 1,000 mg, which is 1,000 ÷ 20 = 50 mg/kg/day. This is above the listed maximum of 45 mg/kg/day, so the nurse holds the dose and clarifies the order before giving it.$q$,$q${"a":{"is_correct":true,"explanation":"The daily dose of 1,000 mg is 50 mg/kg/day, above the maximum of 45, so the nurse holds it and clarifies with the prescriber."},"b":{"is_correct":false,"explanation":"The daily dose is above the safe range, so giving it is unsafe."},"c":{"is_correct":false,"explanation":"Changing the dose on the nurse's own judgment is outside the nurse's role; the prescriber must clarify the order."},"d":{"is_correct":false,"explanation":"Monitoring does not make an unsafe dose safe."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$A child who weighs 20 kg is prescribed amoxicillin 500 mg by mouth every 12 hours. The drug guide lists a safe range of 25 to 45 mg/kg/day in divided doses. What should the nurse do?$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Pharmacology$q$,$q$mcq$q$,$q$A prescriber orders furosemide 40 mg IV push. Hospital policy states that the drug must not be given faster than 20 mg/min. Over what minimum time should the nurse administer the dose?$q$,$q$[{"id":"a","text":"0.5 minute"},{"id":"b","text":"1 minute"},{"id":"c","text":"2 minutes"},{"id":"d","text":"4 minutes"}]$q$::jsonb,$q${"ids":["c"]}$q$::jsonb,$q$Minimum time = dose ÷ maximum rate = 40 mg ÷ 20 mg/min = 2 minutes. Giving it faster raises the risk of hearing loss (ototoxicity) and hypotension.$q$,'draft',$q$Pharmacological and Parenteral Therapies$q$,$q$Take Action$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic C08 (Part C); intended difficulty medium; subtopic: IV push administration time.$q$,$q$Minimum time = dose ÷ maximum rate = 40 mg ÷ 20 mg/min = 2 minutes. Giving it faster raises the risk of hearing loss (ototoxicity) and hypotension.$q$,$q${"a":{"is_correct":false,"explanation":"This would push 40 mg in 30 seconds, four times the maximum rate."},"b":{"is_correct":false,"explanation":"This would push 40 mg in 1 minute, twice the maximum rate."},"c":{"is_correct":true,"explanation":"This is correct: 40 mg at no more than 20 mg/min takes at least 2 minutes."},"d":{"is_correct":false,"explanation":"This is slower than necessary; the question asks for the minimum time."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$A prescriber orders furosemide 40 mg IV push. Hospital policy states that the drug must not be given faster than 20 mg/min. Over what minimum time should the nurse administer the dose?$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Pharmacology$q$,$q$mcq$q$,$q$An antibiotic 100 mL IV piggyback is prescribed to infuse over 30 minutes by pump. At what rate in mL/hr should the nurse program the pump?$q$,$q$[{"id":"a","text":"50 mL/hr"},{"id":"b","text":"100 mL/hr"},{"id":"c","text":"150 mL/hr"},{"id":"d","text":"200 mL/hr"}]$q$::jsonb,$q${"ids":["d"]}$q$::jsonb,$q$Pumps are programmed in mL/hr. 100 mL over 30 minutes is 100 mL ÷ 0.5 hour = 200 mL/hr.$q$,'draft',$q$Pharmacological and Parenteral Therapies$q$,$q$Take Action$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic C09 (Part C); intended difficulty easy; subtopic: IV piggyback rate.$q$,$q$Pumps are programmed in mL/hr. 100 mL over 30 minutes is 100 mL ÷ 0.5 hour = 200 mL/hr.$q$,$q${"a":{"is_correct":false,"explanation":"This rate would take 2 hours to infuse 100 mL."},"b":{"is_correct":false,"explanation":"This rate would take 1 hour to infuse 100 mL."},"c":{"is_correct":false,"explanation":"This rate would take 40 minutes to infuse 100 mL."},"d":{"is_correct":true,"explanation":"This is correct: 100 mL over 30 minutes is 200 mL/hr."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$An antibiotic 100 mL IV piggyback is prescribed to infuse over 30 minutes by pump. At what rate in mL/hr should the nurse program the pump?$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Pharmacology$q$,$q$mcq$q$,$q$A prescriber orders dopamine 5 mcg/kg/min for a client who weighs 80 kg. The premixed bag contains 400 mg in 250 mL. At what rate in mL/hr should the nurse set the pump?$q$,$q$[{"id":"a","text":"7.5 mL/hr"},{"id":"b","text":"15 mL/hr"},{"id":"c","text":"24 mL/hr"},{"id":"d","text":"30 mL/hr"}]$q$::jsonb,$q${"ids":["b"]}$q$::jsonb,$q$The dose is 5 mcg/kg/min × 80 kg = 400 mcg/min, or 24,000 mcg/hr. The concentration is 400,000 mcg ÷ 250 mL = 1,600 mcg/mL. The rate is 24,000 ÷ 1,600 = 15 mL/hr.$q$,'draft',$q$Pharmacological and Parenteral Therapies$q$,$q$Take Action$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic C10 (Part C); intended difficulty hard; subtopic: Titrated infusion (mcg/kg/min).$q$,$q$The dose is 5 mcg/kg/min × 80 kg = 400 mcg/min, or 24,000 mcg/hr. The concentration is 400,000 mcg ÷ 250 mL = 1,600 mcg/mL. The rate is 24,000 ÷ 1,600 = 15 mL/hr.$q$,$q${"a":{"is_correct":false,"explanation":"This rate delivers about 2.5 mcg/kg/min, half the ordered dose."},"b":{"is_correct":true,"explanation":"This is correct: 400 mcg/min is 24,000 mcg/hr, and at 1,600 mcg/mL the rate is 15 mL/hr."},"c":{"is_correct":false,"explanation":"This confuses the 24 mg/hr dose with the mL/hr rate."},"d":{"is_correct":false,"explanation":"This rate delivers about 10 mcg/kg/min, double the ordered dose."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$A prescriber orders dopamine 5 mcg/kg/min for a client who weighs 80 kg. The premixed bag contains 400 mg in 250 mL. At what rate in mL/hr should the nurse set the pump?$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Leadership and Delegation$q$,$q$mcq$q$,$q$During shift report, a nurse receives information about four clients. Which client should the nurse assess first?$q$,$q$[{"id":"a","text":"A client admitted 30 minutes ago who now reports new chest pressure and shortness of breath"},{"id":"b","text":"A client with type 2 diabetes with a glucose of 188 mg/dL before lunch"},{"id":"c","text":"A client on postoperative day 1 who rates incisional pain 4/10"},{"id":"d","text":"A client with COPD whose SpO2 is 91% on room air, which is the client's baseline"}]$q$::jsonb,$q${"ids":["a"]}$q$::jsonb,$q$New chest pressure with shortness of breath may indicate a life-threatening cardiac or pulmonary event and is an acute change. The other clients are stable or at their baseline.$q$,'draft',$q$Management of Care$q$,$q$Prioritize Hypotheses$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic D01 (Part D); intended difficulty easy; subtopic: Prioritizing client assessment.$q$,$q$New chest pressure with shortness of breath may indicate a life-threatening cardiac or pulmonary event and is an acute change. The other clients are stable or at their baseline.$q$,$q${"a":{"is_correct":true,"explanation":"New chest pressure with shortness of breath is an acute, potentially life-threatening change."},"b":{"is_correct":false,"explanation":"A glucose of 188 mg/dL before lunch is not an emergency."},"c":{"is_correct":false,"explanation":"Pain of 4/10 on the first postoperative day is expected and not urgent."},"d":{"is_correct":false,"explanation":"A baseline SpO2 of 91% is expected in COPD, so this client is stable."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$During shift report, a nurse receives information about four clients. Which client should the nurse assess first?$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Leadership and Delegation$q$,$q$mcq$q$,$q$Which task may the registered nurse delegate to an assistive personnel (UAP)?$q$,$q$[{"id":"a","text":"Evaluate a client's response to a PRN analgesic"},{"id":"b","text":"Teach a client how to self-administer insulin"},{"id":"c","text":"Assess a client's new onset of chest pain"},{"id":"d","text":"Obtain vital signs for a stable postoperative client"}]$q$::jsonb,$q${"ids":["d"]}$q$::jsonb,$q$Assessment, teaching and evaluation cannot be delegated. Taking vital signs on a stable client is a routine task within the UAP role, and the nurse then interprets the results.$q$,'draft',$q$Management of Care$q$,$q$Take Action$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic D02 (Part D); intended difficulty easy; subtopic: Delegation to UAP.$q$,$q$Assessment, teaching and evaluation cannot be delegated. Taking vital signs on a stable client is a routine task within the UAP role, and the nurse then interprets the results.$q$,$q${"a":{"is_correct":false,"explanation":"Evaluating a response to medication cannot be delegated."},"b":{"is_correct":false,"explanation":"Client teaching cannot be delegated."},"c":{"is_correct":false,"explanation":"Assessing new chest pain requires the nurse's judgment and cannot be delegated."},"d":{"is_correct":true,"explanation":"Vital signs on a stable client are a routine task within the UAP role."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$Which task may the registered nurse delegate to an assistive personnel (UAP)?$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Leadership and Delegation$q$,$q$mcq$q$,$q$The charge nurse is making assignments. Which client is most appropriate to assign to a licensed practical nurse (LPN/LVN)?$q$,$q$[{"id":"a","text":"A client who needs a comprehensive discharge teaching plan"},{"id":"b","text":"A newly admitted client who needs a comprehensive initial assessment"},{"id":"c","text":"A client with stable chronic heart failure who needs oral medications and routine monitoring"},{"id":"d","text":"A client with an unstable gastrointestinal bleed"}]$q$::jsonb,$q${"ids":["c"]}$q$::jsonb,$q$LPNs care for stable clients with predictable outcomes. Unstable clients, initial comprehensive assessment and development of teaching plans belong to the registered nurse.$q$,'draft',$q$Management of Care$q$,$q$Take Action$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic D03 (Part D); intended difficulty medium; subtopic: Assignment to LPN/LVN.$q$,$q$LPNs care for stable clients with predictable outcomes. Unstable clients, initial comprehensive assessment and development of teaching plans belong to the registered nurse.$q$,$q${"a":{"is_correct":false,"explanation":"Developing a teaching plan is a registered nurse responsibility."},"b":{"is_correct":false,"explanation":"A comprehensive initial assessment is a registered nurse responsibility."},"c":{"is_correct":true,"explanation":"LPNs can care for stable clients with predictable outcomes and routine medications."},"d":{"is_correct":false,"explanation":"An unstable bleed needs the registered nurse's assessment and judgment."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$The charge nurse is making assignments. Which client is most appropriate to assign to a licensed practical nurse (LPN/LVN)?$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Leadership and Delegation$q$,$q$mcq$q$,$q$After receiving report, which task should the nurse complete first?$q$,$q$[{"id":"a","text":"Reinforce discharge teaching for a client who is going home"},{"id":"b","text":"Administer a scheduled 0900 oral medication to a stable client"},{"id":"c","text":"Assess a client whom the assistive personnel reports has new facial droop and slurred speech"},{"id":"d","text":"Document the morning assessments"}]$q$::jsonb,$q${"ids":["c"]}$q$::jsonb,$q$New facial droop and slurred speech are signs of a possible stroke and are time-critical. Scheduled medications, teaching and documentation can safely wait.$q$,'draft',$q$Management of Care$q$,$q$Prioritize Hypotheses$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic D04 (Part D); intended difficulty easy; subtopic: Task prioritization.$q$,$q$New facial droop and slurred speech are signs of a possible stroke and are time-critical. Scheduled medications, teaching and documentation can safely wait.$q$,$q${"a":{"is_correct":false,"explanation":"Discharge teaching can be done after urgent needs are met."},"b":{"is_correct":false,"explanation":"A scheduled oral medication for a stable client can wait."},"c":{"is_correct":true,"explanation":"New facial droop and slurred speech may be a stroke and are time-critical."},"d":{"is_correct":false,"explanation":"Documentation is done after client needs are addressed."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$After receiving report, which task should the nurse complete first?$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Leadership and Delegation$q$,$q$sata$q$,$q$Which tasks can the registered nurse delegate to an assistive personnel (UAP)? Select all that apply.$q$,$q$[{"id":"a","text":"Reinforce teaching about a new insulin regimen"},{"id":"b","text":"Assist a stable client to ambulate to the bathroom"},{"id":"c","text":"Measure and record intake and output for a stable client"},{"id":"d","text":"Assess skin integrity and stage a pressure injury"},{"id":"e","text":"Provide a bed bath"}]$q$::jsonb,$q${"ids":["b","c","e"]}$q$::jsonb,$q$Intake and output, routine ambulation assistance and bathing are routine tasks for stable clients. Skin assessment and staging and client teaching require the judgment of a registered nurse.$q$,'draft',$q$Management of Care$q$,$q$Take Action$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic D05 (Part D); intended difficulty medium; subtopic: Delegation to UAP.$q$,$q$Intake and output, routine ambulation assistance and bathing are routine tasks for stable clients. Skin assessment and staging and client teaching require the judgment of a registered nurse.$q$,$q${"a":{"is_correct":false,"explanation":"Teaching about a new insulin regimen is a registered nurse responsibility."},"b":{"is_correct":true,"explanation":"Helping a stable client to walk to the bathroom is a routine delegable task."},"c":{"is_correct":true,"explanation":"Intake and output for a stable client is a routine delegable task."},"d":{"is_correct":false,"explanation":"Skin assessment and staging require the registered nurse."},"e":{"is_correct":true,"explanation":"Bathing is a routine task for the UAP."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$Which tasks can the registered nurse delegate to an assistive personnel (UAP)? Select all that apply.$q$);

