select $q$Leadership and Delegation$q$,$q$mcq$q$,$q$Which client should the nurse see first?$q$,$q$[{"id":"a","text":"A client with new atrial fibrillation, HR 148/min, BP 82/50 mmHg, who is dizzy and diaphoretic"},{"id":"b","text":"A client with a urinary tract infection who requests an antibiotic"},{"id":"c","text":"A postoperative client who rates pain 6/10 and requests analgesia"},{"id":"d","text":"A client with a COPD exacerbation who is stable on 2 L/min oxygen with an SpO2 of 92%"}]$q$::jsonb,$q${"ids":["a"]}$q$::jsonb,$q$A rapid rhythm with hypotension, dizziness and diaphoresis shows hemodynamic instability and needs immediate intervention. The other clients are stable and can be seen afterward.$q$,'draft',$q$Management of Care$q$,$q$Prioritize Hypotheses$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic D06 (Part D); intended difficulty medium; subtopic: Unstable versus stable.$q$,$q$A rapid rhythm with hypotension, dizziness and diaphoresis shows hemodynamic instability and needs immediate intervention. The other clients are stable and can be seen afterward.$q$,$q${"a":{"is_correct":true,"explanation":"New atrial fibrillation with hypotension, dizziness and diaphoresis is unstable and needs immediate care."},"b":{"is_correct":false,"explanation":"A urinary tract infection without instability is not urgent."},"c":{"is_correct":false,"explanation":"Pain of 6/10 in a stable postoperative client can wait briefly."},"d":{"is_correct":false,"explanation":"A COPD client who is stable on 2 L oxygen can be seen after the unstable client."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$Which client should the nurse see first?$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Leadership and Delegation$q$,$q$mcq$q$,$q$The charge nurse is reviewing the assignments for the shift. Which assignment should the charge nurse question?$q$,$q$[{"id":"a","text":"An assistive personnel is assigned to help two clients with bathing"},{"id":"b","text":"An RN caring for a client with active pulmonary tuberculosis is also assigned to a client who is severely immunocompromised after a stem cell transplant"},{"id":"c","text":"An LPN/LVN is assigned a stable client with a chronic condition"},{"id":"d","text":"An RN is assigned two clients in adjacent rooms who have similar diagnoses"}]$q$::jsonb,$q${"ids":["b"]}$q$::jsonb,$q$Assigning one nurse to a client with an airborne infection and to a severely immunocompromised client creates a serious risk of transmission. The other assignments are appropriate for the roles.$q$,'draft',$q$Management of Care$q$,$q$Evaluate Outcomes$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic D07 (Part D); intended difficulty hard; subtopic: Safe assignments.$q$,$q$Assigning one nurse to a client with an airborne infection and to a severely immunocompromised client creates a serious risk of transmission. The other assignments are appropriate for the roles.$q$,$q${"a":{"is_correct":false,"explanation":"Helping two clients bathe is appropriate for a UAP."},"b":{"is_correct":true,"explanation":"This assignment risks transmitting an airborne infection to a severely immunocompromised client."},"c":{"is_correct":false,"explanation":"A stable client with a chronic condition is appropriate for an LPN/LVN."},"d":{"is_correct":false,"explanation":"Two clients with similar diagnoses in adjacent rooms is an efficient, safe assignment."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$The charge nurse is reviewing the assignments for the shift. Which assignment should the charge nurse question?$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Emergency and Critical Care$q$,$q$mcq$q$,$q$A nurse is triaging four clients in the emergency department. Which client has the highest priority?$q$,$q$[{"id":"a","text":"An adult with a forearm laceration that has controlled bleeding"},{"id":"b","text":"An adult with abdominal pain of 5/10 for 2 days"},{"id":"c","text":"A child with a temperature of 38.2°C and ear pain"},{"id":"d","text":"An adult with sudden shortness of breath, stridor, and swelling of the lips after eating shrimp"}]$q$::jsonb,$q${"ids":["d"]}$q$::jsonb,$q$Airway compromise from anaphylaxis is the most immediately life-threatening problem. Airway, breathing and circulation take priority over pain, fever and controlled bleeding.$q$,'draft',$q$Management of Care$q$,$q$Prioritize Hypotheses$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic D08 (Part D); intended difficulty medium; subtopic: Triage.$q$,$q$Airway compromise from anaphylaxis is the most immediately life-threatening problem. Airway, breathing and circulation take priority over pain, fever and controlled bleeding.$q$,$q${"a":{"is_correct":false,"explanation":"A forearm laceration with controlled bleeding is not immediately life-threatening."},"b":{"is_correct":false,"explanation":"Abdominal pain of 5/10 for 2 days is stable and not immediately life-threatening."},"c":{"is_correct":false,"explanation":"A child with a low-grade fever and ear pain is stable."},"d":{"is_correct":true,"explanation":"Stridor and lip swelling show a threatened airway, the highest priority."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$A nurse is triaging four clients in the emergency department. Which client has the highest priority?$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Emergency and Critical Care$q$,$q$mcq$q$,$q$A client develops facial swelling, wheezing, hypotension, and hives minutes after receiving an IV antibiotic. The nurse has stopped the infusion and called for help. Which prescribed intervention should the nurse implement first?$q$,$q$[{"id":"a","text":"Start an IV bolus of 0.9% sodium chloride"},{"id":"b","text":"Administer epinephrine intramuscularly"},{"id":"c","text":"Obtain a full set of vital signs for comparison"},{"id":"d","text":"Administer diphenhydramine intravenously"}]$q$::jsonb,$q${"ids":["b"]}$q$::jsonb,$q$Intramuscular epinephrine is the first-line treatment for anaphylaxis and reverses airway swelling and hypotension. Fluids, antihistamines and full monitoring follow.$q$,'draft',$q$Physiological Adaptation$q$,$q$Take Action$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic D09 (Part D); intended difficulty medium; subtopic: Anaphylaxis.$q$,$q$Intramuscular epinephrine is the first-line treatment for anaphylaxis and reverses airway swelling and hypotension. Fluids, antihistamines and full monitoring follow.$q$,$q${"a":{"is_correct":false,"explanation":"IV fluids are given after epinephrine and must not delay it."},"b":{"is_correct":true,"explanation":"Intramuscular epinephrine is first-line treatment for anaphylaxis."},"c":{"is_correct":false,"explanation":"Full monitoring must not delay epinephrine."},"d":{"is_correct":false,"explanation":"Antihistamines are adjunct treatment and do not reverse airway swelling or shock."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$A client develops facial swelling, wheezing, hypotension, and hives minutes after receiving an IV antibiotic. The nurse has stopped the infusion and called for help. Which prescribed intervention should the nurse implement first?$q$);

insert into public.questions(topic,question_type,prompt,choices,correct_answer,rationale,status,client_need,clinical_judgment,clinical_review_status,source_batch,quality_notes,correct_answer_explanation,option_explanations)
select $q$Emergency and Critical Care$q$,$q$mcq$q$,$q$A client receiving mechanical ventilation suddenly has hypotension, absent breath sounds on the right, tracheal deviation to the left, and distended neck veins. What should the nurse do first?$q$,$q$[{"id":"a","text":"Administer a PRN sedative"},{"id":"b","text":"Increase the ventilator rate"},{"id":"c","text":"Notify the provider immediately and prepare for emergency needle decompression while maintaining oxygenation"},{"id":"d","text":"Obtain a portable chest x-ray and wait for the results before acting"}]$q$::jsonb,$q${"ids":["c"]}$q$::jsonb,$q$These findings indicate a tension pneumothorax, which compresses the heart and lungs and can cause cardiac arrest within minutes. It is treated clinically with immediate decompression, not after imaging.$q$,'draft',$q$Physiological Adaptation$q$,$q$Prioritize Hypotheses$q$,'pending',$q$diagnostic-parts-b-d-2026-09$q$,$q$DRAFT for clinical review. Requires an approving clinical reviewer and structured references before publication. Diagnostic D10 (Part D); intended difficulty hard; subtopic: Tension pneumothorax.$q$,$q$These findings indicate a tension pneumothorax, which compresses the heart and lungs and can cause cardiac arrest within minutes. It is treated clinically with immediate decompression, not after imaging.$q$,$q${"a":{"is_correct":false,"explanation":"Sedation would worsen instability and does not treat the cause."},"b":{"is_correct":false,"explanation":"Increasing the ventilator rate raises chest pressure and can worsen the tension."},"c":{"is_correct":true,"explanation":"These signs indicate a tension pneumothorax that needs immediate decompression."},"d":{"is_correct":false,"explanation":"Waiting for imaging delays lifesaving decompression."}}$q$::jsonb
where not exists(select 1 from public.questions q where q.prompt=$q$A client receiving mechanical ventilation suddenly has hypotension, absent breath sounds on the right, tracheal deviation to the left, and distended neck veins. What should the nurse do first?$q$);
